import fs from 'node:fs/promises';
import path from 'node:path';
import { DATA_DIR } from '../db.js';

const BLOB_DIR = path.join(DATA_DIR, 'blobs');

// Object keys are generated by the server (random UUIDs), never by the
// user, so they are safe to use as file names.
export function localStorage() {
  return {
    async put(key, buffer) {
      const target = path.join(BLOB_DIR, key);
      await fs.mkdir(path.dirname(target), { recursive: true });
      await fs.writeFile(target, buffer);
    },
    async get(key) {
      return fs.readFile(path.join(BLOB_DIR, key));
    },
    async remove(key) {
      await fs.rm(path.join(BLOB_DIR, key), { force: true });
    },
  };
}
